import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

/*
 * Playdesk Button, the desk's download pill.
 *
 * A vertical gradient for body, a gloss sheen over it for light, and a wide
 * soft shadow for height. Fully rounded at every size; the label sits at medium
 * weight so the shape carries the emphasis.
 */

const buttonVariants = cva(
  [
    "inline-flex items-center justify-center gap-2 whitespace-nowrap",
    "rounded-full text-sm font-medium cursor-pointer select-none",
    "transition-[box-shadow,background-image,transform] duration-fast ease-out",
    "focus-visible:outline-none focus-visible:ring-[0.1875rem] focus-visible:ring-ring/35",
    "disabled:pointer-events-none disabled:opacity-50",
    "active:translate-y-px",
    "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: [
          "text-primary-foreground",
          "[background-image:var(--fill-primary)] [box-shadow:var(--shadow-primary)]",
          "hover:[background-image:var(--fill-primary-hover)] hover:[box-shadow:var(--shadow-primary-hover)]",
        ].join(" "),
        primary: [
          "text-primary-foreground",
          "[background-image:var(--fill-primary)] [box-shadow:var(--shadow-primary)]",
          "hover:[background-image:var(--fill-primary-hover)] hover:[box-shadow:var(--shadow-primary-hover)]",
        ].join(" "),
        secondary: [
          "text-secondary-foreground",
          "[background-image:var(--fill-secondary)] [box-shadow:var(--shadow-button)]",
          "hover:[background-image:var(--fill-secondary-hover)] hover:[box-shadow:var(--shadow-button-hover)]",
        ].join(" "),
        outline:
          "bg-card text-foreground border border-border [box-shadow:var(--shadow-xs)] hover:bg-muted hover:border-foreground/20",
        ghost: "text-foreground hover:bg-foreground/[0.05]",
        destructive: [
          "text-destructive-foreground",
          "[background-image:var(--fill-destructive)] [box-shadow:var(--shadow-destructive)]",
          "hover:[background-image:var(--fill-destructive-hover)] hover:[box-shadow:var(--shadow-destructive-hover)]",
        ].join(" "),
        link: "text-primary font-semibold underline-offset-4 hover:underline",
      },
      size: {
        default: "h-10 px-5",
        sm: "h-8 px-3.5 text-xs",
        lg: "h-12 px-7 text-base",
        icon: "h-10 w-10 px-0",
        "icon-sm": "h-8 w-8 px-0",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  }
)

export interface ButtonProps
  extends Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof buttonVariants> {
  className?: string
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, children, ...props }, ref) => {
    const classes = cn(buttonVariants({ variant, size, className }))

    // Callers written against the Radix API pass the element to become as a
    // child: <Button asChild><Link>…</Link></Button>. Base UI has no asChild,
    // it composes through `render`. Without this the prop reaches the DOM and
    // the anchor nests inside the button instead of replacing it, which stacks
    // the icon above the label and puts a link inside a button.
    if (asChild && React.isValidElement(children)) {
      return (
        <ButtonPrimitive
          ref={ref}
          className={classes}
          {...props}
          // After the spread, so an explicit asChild child wins over a stray
          // render prop rather than being silently replaced by it.
          // SAFETY: this branch runs only when `asChild` is set, and the caller then
          // owns passing a single element for the slot to clone.
          render={children as React.ReactElement}
        />
      )
    }

    return (
      <ButtonPrimitive ref={ref} className={classes} {...props}>
        {children}
      </ButtonPrimitive>
    )
  }
)
Button.displayName = "Button"

export { Button, buttonVariants }
